item.command:
/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['openpyxl','xlsx2csv']:
 try:
  with urllib.request.urlopen(f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=20&onlyActiveTags=true', timeout=30) as x: d=json.load(x)
  print(repo, [t['name'] for t in d.get('tags',[])[:8]])
 except Exception as e: print(repo, type(e).__name__)
PY"

/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['openpyxl','xlsx2csv']:
 try:
  with urllib.request.urlopen(f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=20&onlyActiveTags=true', timeout=30) as x: d=json.load(x)
  print(repo, [t['name'] for t in d.get('tags',[])[:8]])
 except Exception as e: print(repo, type(e).__name__)
PY"

